arguments.command:
cd /tmp/sv-b8b4b616e2e24333934809dbc0821773/moderate-version-conflicts && dotnet package list --format json 2>/dev/null | python3 -m json.tool > after-cpm-packages.json && python3 -c "
import json
with open('baseline-packages.json') as f: baseline = json.load(f)
with open('after-cpm-packages.json') as f: after = json.load(f)

def extract(data):
    pkgs = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            for pkg in fw.get('topLevelPackages', []):
                key = (pname, pkg['id'])
                pkgs[key] = pkg['resolvedVersion']
    return pkgs

b = extract(baseline)
a = extract(after)
changes = []
for k in sorted(set(list(b.keys()) + list(a.keys()))):
    bv = b.get(k, '—')
    av = a.get(k, '—')
    if bv != av:
        changes.append((k[0], k[1], bv, av))

if changes:
    print('CHANGES:')
    for proj, pkg, bv, av in changes:
        print(f'  {proj} | {pkg} | {bv} -> {av}')
else:
    print('No changes detected')

print()
print('ALL PACKAGES:')
for k in sorted(a.keys()):
    print(f'  {k[0]} | {k[1]} | {a[k]}')
"

